parameters.jsCode:
const item = $input.first().json;
const cfg = {
  jira_base_url: item.jira_base_url,
  jira_project_key: item.jira_project_key,
  jira_issue_type: item.jira_issue_type,
  privacy_sla_days: Number(item.privacy_sla_days || 30),
  bigquery_project_id: item.bigquery_project_id,
  bigquery_dataset: item.bigquery_dataset,
  bigquery_table: item.bigquery_table,
  slack_channel_id: item.slack_channel_id,
  manual_review_label: item.manual_review_label,
  confirmation_email_enabled: item.confirmation_email_enabled === true || item.confirmation_email_enabled === 'true',
  minimum_confidence: Number(item.minimum_confidence || 0.75),
};

const source = item.payload || item.message || item;
const rawSubject = source.subject || item.subject || 'Please delete my account';
const rawFrom = source.from || source.sender || item.from || 'user@example.com';
const rawText = source.textPlain || source.text || source.body || item.text || 'Hello, please delete my personal data from your systems.';
const cleanText = String(rawText)
  .replace(/\r/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/--\s*[\s\S]*$/m, '')
  .trim();

const lower = `${rawSubject} ${cleanText}`.toLowerCase();
const patterns = [
  { type: 'deletion', keywords: ['delete my data', 'erase my data', 'remove my account', 'right to erasure', 'data deletion'] },
  { type: 'access', keywords: ['copy of my data', 'access my data', 'data access request', 'dsar'] },
  { type: 'correction', keywords: ['correct my data', 'update my data', 'rectify'] },
];

let requestType = 'unclear';
let hits = 0;
for (const p of patterns) {
  const score = p.keywords.filter(k => lower.includes(k)).length;
  if (score > hits) {
    hits = score;
    requestType = p.type;
  }
}

const confidence = hits === 0 ? 0.35 : Math.min(0.95, 0.55 + hits * 0.2);
const receivedAt = new Date();
const dueDate = new Date(receivedAt.getTime() + cfg.privacy_sla_days * 24 * 60 * 60 * 1000);

return [{
  json: {
    config: cfg,
    requesterEmail: String(rawFrom).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || rawFrom,
    subject: rawSubject,
    sanitizedPreview: cleanText.slice(0, 500),
    requestType,
    confidence,
    routeToPrivacyTask: confidence >= cfg.minimum_confidence && requestType !== 'unclear',
    receivedAt: receivedAt.toISOString(),
    dueDate: dueDate.toISOString().slice(0, 10),
    sourceMessageId: source.id || item.id || 'manual-test-message',
  }
}];

